INSERT INTO global_skills (id, name, description, content, is_active, created_at) VALUES ('a63c3053ea5949f4b7184d126a003c03', 'ascii-art', 'ASCII art: pyfiglet, cowsay, boxes, image-to-ascii.', '---
name: ascii-art
description: "ASCII art: pyfiglet, cowsay, boxes, image-to-ascii."
version: 4.0.0
author: 0xbyt4, Hermes Agent
license: MIT
dependencies: []
