INSERT INTO global_skills (id, name, description, content, is_active, created_at) VALUES ('01f45613aaca435f8c3e19f9f42fdd34', 'blogwatcher', 'Monitor blogs and RSS/Atom feeds via blogwatcher-cli tool.', '---
name: blogwatcher
description: "Monitor blogs and RSS/Atom feeds via blogwatcher-cli tool."
version: 2.0.0
author: JulienTant (fork of Hyaxia/blogwatcher)
license: MIT
platforms: [linux, macos, windows]
metadata:
  hermes:
    tags: [RSS, Blogs, Feed-Reader, Monitoring]
    homepage: https://github.com/JulienTant/blogwatcher-cli
