INSERT INTO skill_files (id, global_skill_id, user_skill_id, filename, content, encoding, created_at) VALUES ('76452801d5014f9fb894c71771e4f689', '3126ee183b57473da64dfc083d3f84c2', NULL, 'workflows/sd15_txt2img.json', '{
