INSERT INTO skill_files (id, global_skill_id, user_skill_id, filename, content, encoding, created_at) VALUES ('d68fc200245444f493c5ec1f58e3a3f1', '50ee36966e574c66849d1ec1aed0deff', NULL, 'scripts/office/schemas/ISO-IEC29500-4_2016/pml.xsd', '<?xml version="1.0" encoding="utf-8"?>
