INSERT INTO skill_files (id, global_skill_id, user_skill_id, filename, content, encoding, created_at) VALUES ('683b454a3c55463e89314cbce0ac7f99', '50ee36966e574c66849d1ec1aed0deff', NULL, 'scripts/office/schemas/ISO-IEC29500-4_2016/sml.xsd', '<?xml version="1.0" encoding="utf-8"?>
