function setOrbShape(shape, { reveal = false, syncControl = true } = {}) {
  ORB.shape = shape;
  if (syncControl) {
    ctrls.orbShape = shape;
    orbShapeControl?.updateDisplay();
  }
  if (reveal) {
    gsap.killTweensOf(orbCanvas);
    orbCanvas.style.opacity = "1";
