  gsap.killTweensOf(ORB, "shapeMix");
  gsap.to(ORB, {
    shapeMix: shape === "cube" ? 1 : 0,
    duration: Math.max(0.01, ctrls.shapeMorphDuration ?? 0.65),
    ease: "power2.inOut",
    onUpdate: () => { lastTextSignature = ""; },
