INTEGERS { multiresult }

FUNCTION {multi.page.check}
{ ''t :=
  #0 ''multiresult :=
    { multiresult not
      t empty$ not
      and
    }
    { t #1 #1 substring$
      duplicate$ "-" =
      swap$ duplicate$ "," =
      swap$ "+" =
      or or
        { #1 ''multiresult := }
        { t #2 global.max$ substring$ ''t := }
      if$
    }
  while$
  multiresult
}

FUNCTION {format.pages}
