FUNCTION {calc.short.authors}
{ type$ "book" =
  type$ "inbook" =
  or
    ''author.editor.key.label
    { type$ "proceedings" =
        ''editor.key.organization.label
        { type$ "manual" =
            ''author.key.organization.label
            ''author.key.label
          if$
        }
      if$
    }
  if$
  ''short.list :=
}

FUNCTION {calc.label}
{ calc.short.authors
