FUNCTION {presort}
{ calc.label
  label sortify
  "    "
  *
  type$ "book" =
  type$ "inbook" =
  or
    ''author.editor.sort
    { type$ "proceedings" =
        ''editor.organization.sort
        { type$ "manual" =
            ''author.organization.sort
            ''author.sort
          if$
        }
      if$
    }
  if$
  "    "
  *
  year field.or.null sortify
  *
  "    "
  *
  cite$
  *
  #1 entry.max$ substring$
