FUNCTION {default.type} { misc }
READ
FUNCTION {sortify}
{ purify$
  "l" change.case$
}
INTEGERS { len }
FUNCTION {chop.word}
{ ''s :=
  ''len :=
  s #1 len substring$ =
    { s len #1 + global.max$ substring$ }
    ''s
  if$
}
FUNCTION {format.lab.names}
{ ''s :=
  "" ''t :=
  s #1 "{vv~}{ll}" format.name$
  s num.names$ duplicate$
  #2 >
    { pop$
      " " * bbl.etal *
    }
    { #2 <
        ''skip$
        { s #2 "{ff }{vv }{ll}{ jj}" format.name$ "others" =
            {
              " " * bbl.etal *
            }
            { bbl.and space.word * s #2 "{vv~}{ll}" format.name$
              * }
          if$
        }
      if$
    }
  if$
}

FUNCTION {author.key.label}
{ author empty$
    { key empty$
        { cite$ #1 #3 substring$ }
        ''key
      if$
    }
    { author format.lab.names }
  if$
}

FUNCTION {author.editor.key.label}
{ author empty$
    { editor empty$
        { key empty$
            { cite$ #1 #3 substring$ }
            ''key
          if$
        }
        { editor format.lab.names }
      if$
    }
    { author format.lab.names }
  if$
}

FUNCTION {editor.key.label}
{ editor empty$
    { key empty$
        { cite$ #1 #3 substring$ }
        ''key
      if$
    }
    { editor format.lab.names }
  if$
}

FUNCTION {calc.short.authors}
{ type$ "book" =
  type$ "inbook" =
  or
    ''author.editor.key.label
    { type$ "proceedings" =
        ''editor.key.label
        ''author.key.label
      if$
    }
  if$
  ''short.list :=
}

FUNCTION {calc.label}
{ calc.short.authors
  short.list
  "("
  *
  year duplicate$ empty$
  short.list key field.or.null = or
     { pop$ "" }
     ''skip$
  if$
  *
  ''label :=
}

FUNCTION {sort.format.names}
{ ''s :=
  #1 ''nameptr :=
  ""
  s num.names$ ''numnames :=
  numnames ''namesleft :=
    { namesleft #0 > }
    { s nameptr
      "{vv{ } }{ll{ }}{  ff{ }}{  jj{ }}"
      format.name$ ''t :=
      nameptr #1 >
        {
          "   "  *
          namesleft #1 = t "others" = and
            { "zzzzz" ''t := }
            ''skip$
          if$
          t sortify *
        }
        { t sortify * }
      if$
      nameptr #1 + ''nameptr :=
      namesleft #1 - ''namesleft :=
    }
  while$
}

FUNCTION {sort.format.title}
{ ''t :=
  "A " #2
    "An " #3
      "The " #4 t chop.word
    chop.word
  chop.word
  sortify
  #1 global.max$ substring$
}
FUNCTION {author.sort}
{ author empty$
    { key empty$
        { "to sort, need author or key in " cite$ * warning$
          ""
        }
        { key sortify }
      if$
    }
    { author sort.format.names }
  if$
}
FUNCTION {author.editor.sort}
{ author empty$
    { editor empty$
        { key empty$
            { "to sort, need author, editor, or key in " cite$ * warning$
              ""
            }
            { key sortify }
          if$
        }
        { editor sort.format.names }
      if$
    }
    { author sort.format.names }
  if$
}
FUNCTION {editor.sort}
{ editor empty$
    { key empty$
        { "to sort, need editor or key in " cite$ * warning$
          ""
        }
        { key sortify }
      if$
    }
    { editor sort.format.names }
  if$
}
FUNCTION {presort}
{ calc.label
  label sortify
  "    "
  *
  type$ "book" =
  type$ "inbook" =
  or
    ''author.editor.sort
    { type$ "proceedings" =
        ''editor.sort
        ''author.sort
      if$
    }
  if$
  #1 entry.max$ substring$
  ''sort.label :=
  sort.label
  *
  "    "
  *
  title field.or.null
  sort.format.title
  *
  #1 entry.max$ substring$
  ''sort.key$ :=
}

ITERATE {presort}
SORT
STRINGS { last.label next.extra }
INTEGERS { last.extra.num last.extra.num.extended last.extra.num.blank number.label }
FUNCTION {initialize.extra.label.stuff}
{ #0 int.to.chr$ ''last.label :=
  "" ''next.extra :=
  #0 ''last.extra.num :=
  "a" chr.to.int$ #1 - ''last.extra.num.blank :=
  last.extra.num.blank ''last.extra.num.extended :=
  #0 ''number.label :=
}
FUNCTION {forward.pass}
{ last.label label =
    { last.extra.num #1 + ''last.extra.num :=
      last.extra.num "z" chr.to.int$ >
       { "a" chr.to.int$ ''last.extra.num :=
         last.extra.num.extended #1 + ''last.extra.num.extended :=
       }
       ''skip$
      if$
      last.extra.num.extended last.extra.num.blank >
        { last.extra.num.extended int.to.chr$
          last.extra.num int.to.chr$
          * ''extra.label := }
        { last.extra.num int.to.chr$ ''extra.label := }
      if$
    }
    { "a" chr.to.int$ ''last.extra.num :=
      "" ''extra.label :=
      label ''last.label :=
    }
  if$
  number.label #1 + ''number.label :=
}
FUNCTION {reverse.pass}
{ next.extra "b" =
    { "a" ''extra.label := }
    ''skip$
  if$
  extra.label ''next.extra :=
  extra.label
  duplicate$ empty$
    ''skip$
    { year field.or.null #-1 #1 substring$ chr.to.int$ #65 < 
      { "{\natexlab{" swap$ * "}}" * }
      { "{(\natexlab{" swap$ * "})}" * }
    if$ }
  if$
  ''extra.label :=
  label extra.label * ''label :=
}
EXECUTE {initialize.extra.label.stuff}
ITERATE {forward.pass}
REVERSE {reverse.pass}
FUNCTION {bib.sort.order}
{ sort.label
  "    "
  *
  year field.or.null sortify
  *
  "    "
  *
  title field.or.null
  sort.format.title
  *
  #1 entry.max$ substring$
  ''sort.key$ :=
}
ITERATE {bib.sort.order}
SORT
FUNCTION {begin.bib}
{ preamble$ empty$
    ''skip$
    { preamble$ write$ newline$ }
  if$
  "\begin{thebibliography}{" number.label int.to.str$ * "}" *
  write$ newline$
  "\providecommand{\natexlab}[1]{#1}"
  write$ newline$
}
EXECUTE {begin.bib}
EXECUTE {init.urlbst.variables} % urlbst
EXECUTE {init.state.consts}
ITERATE {call.type$}
FUNCTION {end.bib}
{ newline$
  "\end{thebibliography}" write$ newline$
}
EXECUTE {end.bib}
%% End of customized bst file
%%
%% End of file `acl_natbib_basic.bst''.
', 'utf-8', '2026-06-22T06:00:57.423833');
INSERT INTO skill_files (id, global_skill_id, user_skill_id, filename, content, encoding, created_at) VALUES ('fb54f912876e42d4aac9f369b13edc3c', '67a52735f62a4425b6fdba450e8c4fdb', NULL, 'templates/acl/anthology.bib.txt', 'For citing papers in the ACL Anthology, we provide a single consolidated
BibTeX file containing all of its papers. The bibkeys in these papers are
designed to be semantic in nature: {names}-{year}-{words}, where
- `names` is the concatenated last names of the authors when there is just
  one or two authors, or `lastname-etal` for 3+
- `year` is the four-digit year
- `words` is the first significant word in the title, or more, if necessary,
  to preserve uniqueness

For example, https://aclanthology.org/N04-1035 can be cited as \cite{galley-etal-2004-whats}.

The consolidated file can be downloaded from here:
- https://aclanthology.org/anthology.bib

Unfortunately, as of 2024 or so, this file is now larger than 50 MB, which is Overleaf''s
bib file size limit. Consequently, the Anthology shards the file automatically into
49 MB shards.

There are currently (2025) two files:
- https://aclanthology.org/anthology-1.bib
- https://aclanthology.org/anthology-2.bib

You can download these directly from Overleaf from New File -> From External URL,
and then adding them to the \bibliography line in acl_latex.tex:

    \bibliography{custom,anthology-1,anthology-2}
', 'utf-8', '2026-06-22T06:00:57.423836');
INSERT INTO skill_files (id, global_skill_id, user_skill_id, filename, content, encoding, created_at) VALUES ('714551b5545244bfaeb98bf500713e9e', '67a52735f62a4425b6fdba450e8c4fdb', NULL, 'templates/acl/custom.bib', '% Use this file for citations not found in the ACL Anthology (contained in "anthology.bib").

