FUNCTION {format.names}
{ ''bibinfo :=
  duplicate$ empty$ ''skip$ {
  ''s :=
  "" ''t :=
  #1 ''nameptr :=
  s num.names$ ''numnames :=
  numnames ''namesleft :=
    { namesleft #0 > }
    { s nameptr
      "{vv~}{ll}{, f.}{, jj}"
      format.name$
      bibinfo bibinfo.check
      ''t :=
      nameptr #1 >
        {
          namesleft #1 >
            { "; " * t * }
            {
              s nameptr "{ll}" format.name$ duplicate$ "others" =
                { ''t := }
                { pop$ }
              if$
              ";" *
              t "others" =
                {
                  " " * bbl.etal *
                }
                {
                  bbl.and
                  space.word * t *
                }
              if$
            }
          if$
        }
        ''t
      if$
      nameptr #1 + ''nameptr :=
      namesleft #1 - ''namesleft :=
    }
  while$
  } if$
}
