            { ", " * t * }
            {
              s nameptr "{ll}" format.name$ duplicate$ "others" =
                { ''t := }
                { pop$ }
              if$
              t "others" =
                {
                  " " * bbl.etal *
                }
                {
                  numnames #2 >
                    { "," * }
                    ''skip$
                  if$
                  bbl.and
                  space.word * t *
                }
