    \vskip .2em plus 0.25fil%
    {\normalsize \affiliations_\ifhmode\\\fi}%
    \vskip 1em plus 2fil%
  }%
}%
%
\renewenvironment{abstract}{%
  \centerline{\bf Abstract}%
  \vspace{0.5ex}%
  \setlength{\leftmargini}{10pt}%
  \begin{quote}%
    \small%
}{%
  \par%
